+  /* Create every CPU0-only transport worker before enabling SysTick. */
+
+  bk7258_boottrace_primary(BK7258_BOOT_BRINGUP_TIMER_START);
+  ret = bk7258_timer_start();
+  if (ret < 0)
+    {
+      printf("system tick start failed, error=%d\n", ret);
+      return ret;
