+#define BK7258_IPI_TRACE_ENTRY  0xb1000000u
+#define BK7258_IPI_TRACE_CLAIM  0xb2000000u
+#define BK7258_IPI_TRACE_SENT   0xb3000000u
+#define BK7258_IPI_TRACE_FAIL   0xb4000000u
