+      if (ret != -EAGAIN)
+        {
+          atomic_set_release(&g_ipi_kicked[cpu], 0);
+          bk7258_smp_trace(BK7258_IPI_TRACE_FAIL |
+                           ((uint32_t)(-ret) & 0xffffu));
+          return ret;
+        }
