+    {
+      uint32_t pending = atomic_xchg_acquire(&g_ipi_pending[cpu], 0);
+
+      if ((pending & BK7258_IPI_CALL) != 0)
+        {
+          nxsched_smp_call_handler(irq, context, NULL);
+        }
